for module,names in expected.items():
    base=Path('android')/module/'build'
    files=list((base/('test-results/test' if module=='core' else 'outputs/androidTest-results')).rglob('TEST-*.xml'))
    assert files, f'{module}: XML absent'
    actual=[]
    for f in files:
        root=E.parse(f).getroot()
        for suite in root.iter():
            if suite.tag not in ('testsuite','testsuites'): continue
            for key in ('failures','errors','skipped'):
                value=suite.get(key,'0')
                assert value.isascii() and value.isdecimal() and int(value)==0, f'{module}: nonzero/malformed {key}'
            count=suite.get('tests','')
            assert count.isascii() and count.isdecimal() and int(count)==sum(1 for _ in suite.iter('testcase')), f'{module}: tests count mismatch/malformed'
        assert not list(root.iter('failure')) and not list(root.iter('error')) and not list(root.iter('skipped')), f'{module}: failed/error/skipped'
        actual += [t.attrib['classname']+'#'+t.attrib['name'] for t in root.iter('testcase')]
    assert Counter(actual)==Counter(names), f'{module}: exact method set differs, missing={Counter(names)-Counter(actual)}, unexpected={Counter(actual)-Counter(names)}'
    print('EXACT_SYNTHETIC_METHODS',module,len(actual),'zero failures/errors/skips')
